def findAll(arr, n, asum):
	dp = {0}
	arr = filter(lambda x: x <= asum, arr)
	for note in arr:
		new_sums = set(map(lambda x: x + note, dp))
		if asum in new_sums:
			return 'Yes'
		dp = dp.union(new_sums)
	else:
		return 'No'

def main():
	for _ in range(int(input())):
		(n, m) = map(int, input().split())
		arr = map(int, [input() for _ in range(n)])
		ans = findAll(arr, n, m)
		print(ans)
main()
